static constexpr uint64_t benchmarkServiceServerID = 5020138136299466188UL;
static constexpr uint64_t benchmarkServiceServer_CallID = 15818830462261156317UL;

class BenchmarkServiceServer {
public:
	virtual ~BenchmarkServiceServer() = default;
	
	virtual std::pair<::benchmark::Response, scg::error::Error> call(const scg::context::Context& ctx, const ::benchmark::Request& req) = 0;
	
};

class BenchmarkService_ServerStub {
public:
	BenchmarkService_ServerStub(std::shared_ptr<BenchmarkServiceServer> impl) : impl_(impl) {}

	
	std::vector<uint8_t> handleCall(const scg::context::Context& ctx, const std::vector<scg::middleware::Middleware>& middleware, uint64_t requestID, scg::serialize::Reader& reader) {
		::benchmark::Request req;
		auto err = reader.read(req);
		if (err) {
			return scg::rpc::respondWithError(requestID, err);
		}

		auto handler = [this](scg::context::Context& handlerCtx, const scg::type::Message& r) -> std::pair<std::shared_ptr<scg::type::Message>, scg::error::Error> {
			// handle the request passed down the middleware chain, which a
			// middleware may have replaced
			const auto* typedReq = dynamic_cast<const ::benchmark::Request*>(&r);
			if (!typedReq) {
				return std::make_pair(nullptr, scg::error::Error("Invalid request type"));
			}
			auto [resp, handlerErr] = impl_->call(handlerCtx, *typedReq);
			if (handlerErr) {
				return std::make_pair(nullptr, handlerErr);
			}
			return std::make_pair(std::make_shared<::benchmark::Response>(std::move(resp)), nullptr);
		};

		auto result = scg::middleware::applyHandlerChain(const_cast<scg::context::Context&>(ctx), req, middleware, handler);
		if (result.second) {
			return scg::rpc::respondWithError(requestID, result.second);
		}

		auto resp = std::dynamic_pointer_cast<::benchmark::Response>(result.first);
		if (!resp) {
			return scg::rpc::respondWithError(requestID, scg::error::Error("Invalid response type"));
		}

		auto response = scg::rpc::respondWithMessage(requestID, *resp);
		return response;
	}
	
	std::vector<uint8_t> handleWrapper(const scg::context::Context& ctx, const std::vector<scg::middleware::Middleware>& middleware, uint64_t requestID, scg::serialize::Reader& reader) {
		uint64_t methodID = 0;
		auto err = reader.read(methodID);
		if (err) {
			return scg::rpc::respondWithError(requestID, err);
		}
		switch (methodID) {
		case benchmarkServiceServer_CallID:
			return handleCall(ctx, middleware, requestID, reader);
		default:
			return scg::rpc::respondWithError(requestID, scg::error::Error("Unrecognized method ID: " + std::to_string(methodID)));
		}
	}

	scg::error::Error handleStreamWrapper(const scg::context::Context& ctx, std::shared_ptr<scg::rpc::ServerStream> stream, uint64_t methodID) {
		(void)ctx;
		// no streaming methods
		(void)stream;
		return scg::error::Error("Unrecognized stream method ID: " + std::to_string(methodID));
	}

private:
	std::shared_ptr<BenchmarkServiceServer> impl_;
};

inline void registerBenchmarkServiceServer(scg::rpc::Server* server, std::shared_ptr<BenchmarkServiceServer> impl) {
	auto stub = std::make_shared<BenchmarkService_ServerStub>(impl);

	auto handler = [stub](const scg::context::Context& ctx, const std::vector<scg::middleware::Middleware>& middleware, uint64_t requestID, scg::serialize::Reader& reader) -> std::vector<uint8_t> {
		return stub->handleWrapper(ctx, middleware, requestID, reader);
	};

	server->registerService(benchmarkServiceServerID, "BenchmarkService", handler);

	auto streamHandler = [stub](const scg::context::Context& ctx, std::shared_ptr<scg::rpc::ServerStream> stream, uint64_t methodID) -> scg::error::Error {
		return stub->handleStreamWrapper(ctx, stream, methodID);
	};

	server->registerStreamService(benchmarkServiceServerID, streamHandler);
}


static constexpr uint64_t benchmarkServiceID = 5020138136299466188UL;
static constexpr uint64_t benchmarkService_CallID = 15818830462261156317UL;

// BenchmarkServiceApi is the abstract call surface of the BenchmarkService service,
// mirroring the client call shape one-to-one. BenchmarkServiceClient is the RPC-backed
// implementation; tests (or alternative transports) substitute their own. Symmetric to the
// server-side BenchmarkServiceServer interface. Only unary rpcs are part of the interface;
// streaming rpcs stay on the concrete client.
class BenchmarkServiceApi {
public:
	virtual ~BenchmarkServiceApi() = default;
	
	virtual std::pair<::benchmark::Response, scg::error::Error> call(scg::context::Context& ctx, const ::benchmark::Request& req) = 0;
	
};

class BenchmarkServiceClient final : public BenchmarkServiceApi {
public:
	// Takes ownership of client and deletes it when the last copy of this
	// object is destroyed. Deprecated because that is easy to misuse (passing a
	// pointer owned elsewhere double-deletes it).
	[[deprecated("takes ownership of the raw pointer; pass a std::shared_ptr<scg::rpc::Client>, or a scg::rpc::Client& for a non-owning client")]]
	inline explicit
	BenchmarkServiceClient(scg::rpc::Client* client) : client_(client) {}

	// Non-owning: the caller must keep client alive for the lifetime of this object.
	inline explicit
	BenchmarkServiceClient(scg::rpc::Client& client) : client_(std::shared_ptr<scg::rpc::Client>(), &client) {}

	inline explicit
	BenchmarkServiceClient(std::shared_ptr<scg::rpc::Client> client) : client_(std::move(client)) {}
	
	inline std::pair<::benchmark::Response, scg::error::Error> call(scg::context::Context& ctx, const ::benchmark::Request& req) override
	{
		::benchmark::Response resp;
		auto err = call(&resp, ctx, req);
		return std::pair(std::move(resp), err);
	}

	inline scg::error::Error call(::benchmark::Response* resp, scg::context::Context& c, const ::benchmark::Request& req) const
	{
		auto handler = [this, resp](scg::context::Context& ctx, const scg::type::Message& r) -> std::pair<std::shared_ptr<scg::type::Message>, scg::error::Error> {
			// send the request passed down the middleware chain, which a
			// middleware may have replaced
			const auto* typedReq = dynamic_cast<const ::benchmark::Request*>(&r);
			if (!typedReq) {
				return std::make_pair(nullptr, scg::error::Error("Invalid request type"));
			}
			auto [reader, err] = client_->call(ctx, benchmarkServiceID, benchmarkService_CallID, *typedReq);
			if (err) {
				return std::make_pair(nullptr, err);
			}

			err = reader.read(*resp);
			if (err) {
				return std::make_pair(nullptr, err);
			}

			return std::make_pair(std::shared_ptr<scg::type::Message>(resp, [](scg::type::Message*){}), nullptr);
		};

		auto& middleware = client_->middleware();
		return scg::middleware::applyHandlerChain(c, req, middleware, handler).second;
	}
	

private:
	std::shared_ptr<scg::rpc::Client> client_;
};

// BenchmarkServiceFake is a test double for BenchmarkServiceApi: each method invokes
// its hook when set, otherwise returns a default-constructed response with no error. Deliberately
// minimal — no built-in call recording or thread-safety; layer those per the test's own needs.
class BenchmarkServiceFake : public BenchmarkServiceApi {
public:
	std::function<std::pair<::benchmark::Response, scg::error::Error>(scg::context::Context&, const ::benchmark::Request&)> onCall;
	
	std::pair<::benchmark::Response, scg::error::Error> call(scg::context::Context& ctx, const ::benchmark::Request& req) override
	{
		if (onCall) {
			return onCall(ctx, req);
		}
		return { ::benchmark::Response{}, nullptr };
	}
	
};

